// Precalculate exact cumulative distances and total route distance for all datasets
(function() {
    for (const key in NAVDRISHTI_DATASETS) {
        const ds = NAVDRISHTI_DATASETS[key];
        if (ds && ds.points && ds.points.length > 0) {
            let cum = 0;
            ds.points[0].cumulativeDist = 0;
            for (let i = 1; i < ds.points.length; i++) {
                const p1 = ds.points[i - 1];
                const p2 = ds.points[i];
                const d = Math.hypot(p2.truth.north - p1.truth.north, p2.truth.east - p1.truth.east);
                cum += d;
                p2.cumulativeDist = cum;
            }
            ds.totalDistanceM = cum;
        }
    }
})();

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { NAVDRISHTI_DATASETS };
}
